__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"default",{enumerable:!0,get:function(){return o}});var o={tela:{titulo:'A idade real de cada coisa',subtitulo:'Parece milenar \xd7 tem certid\xe3o de nascimento',intro:'Trinta coisas que o mercado vende como antigas, com o ano em que cada uma apareceu. A lista abre pela mais nova.',ordenarPor:'ORDENAR',ordemMaisNovo:'Mais nova primeiro',ordemMaisAntigo:'Mais antiga primeiro',ordemTema:'Por tema',rotuloQuem:'QUEM INVENTOU',rotuloQuando:'QUANDO',recibo:'RECIBO',abrir:'Ver a hist\xf3ria',fechar:'Fechar',compartilhar:'Compartilhar',copiado:'Texto copiado \u2014 cola onde quiser.',naoCopiou:'N\xe3o deu pra copiar aqui \u2014 seleciona o texto e copia.',idadeAnos:'{n} anos',idadeAnosAprox:'cerca de {n} anos',semData:'sem data',semDataLonga:'A pesquisa procurou o inventor e n\xe3o achou. Fica declarado.',comoContamos:'A idade aqui \xe9 conta, n\xe3o tabela: {ano} menos o ano que a fonte d\xe1. Por isso ela vira sozinha na virada do ano.',progresso:'Voc\xea j\xe1 abriu {n} de {total}.',marca:'cosmicguide.cloud'},formato:{separadorMilhar:'.'},temas:{zodiaco:'O zod\xedaco',mapa:'O mapa',planetas:'Os planetas',lua:'A Lua',oraculos:'Os or\xe1culos',leitura:'O jeito de ler',mercado:'O mercado'},graus:{FP:{nome:'fonte prim\xe1ria',glosa:'o texto antigo diz isso, e a pesquisa aponta obra e cap\xedtulo'},TP:{nome:'tradi\xe7\xe3o posterior',glosa:'surgiu depois do mundo antigo, com autor e data conhecidos'},IR:{nome:'inven\xe7\xe3o recente',glosa:'n\xe3o tem raiz antiga: nasceu nos s\xe9culos XIX, XX ou XXI'},AM:{nome:'academia moderna',glosa:'\xe9 conclus\xe3o de pesquisa hist\xf3rica, dos s\xe9culos XIX ao XXI'}},compartilhar:{idade:'Idade real:',pensam:'O que pensam:',quem:'Quem inventou:',recibo:'Recibo:'},itens:{'zodiaco-12':{coisa:'O zod\xedaco de doze signos de 30\xb0',oQuePensam:'Tem 5.000 anos e \xe9 a coisa mais antiga da astrologia.',quemInventou:'os astr\xf4nomos da Babil\xf4nia',quando:'c. 450\u2013400 a.C.',fonte:'Babil\xf4nia, c. 450\u2013400 a.C.',detalhe:'Esta \xe9 a linha em que a resposta honesta impressiona mais que o chute redondo. Os babil\xf4nios trocaram as constela\xe7\xf5es, que t\xeam tamanhos bem diferentes, por doze fatias iguais de 30\xb0 na ecl\xedptica \u2014 a faixa do c\xe9u por onde o Sol parece caminhar. Sem essa grade n\xe3o existe dizer "Marte em G\xeameos" como coordenada, e \xe9 sobre ela que roda a astrologia inteira at\xe9 hoje.'},'homem-zodiacal':{coisa:'O Homem Zodiacal, que d\xe1 a cada signo uma parte do corpo',oQuePensam:'Est\xe1 no Tetrabiblos, \xe9 lista de Ptolomeu.',quemInventou:'Man\xedlio, no poema Astronomica',quando:'s\xe9c. I d.C.',fonte:'Man\xedlio, Astronomica II.453\u2013465, s\xe9c. I; corroborado por V\xe9tio Valente',detalhe:'A lista que reparte o corpo entre os doze signos n\xe3o est\xe1 onde todo mundo jura que est\xe1. Ptolomeu enumera a correspond\xeancia dos planetas; quem escreve a dos signos \xe9 Man\xedlio, num poema em versos. E nela Le\xe3o n\xe3o fica com o cora\xe7\xe3o \u2014 fica com os flancos e as omoplatas.'},'mapa-natal':{coisa:'O mapa natal com Ascendente e casas',oQuePensam:'Os babil\xf4nios j\xe1 liam mapa natal, h\xe1 5.000 anos.',quemInventou:'autores gregos de Alexandria, sob os pseud\xf4nimos Nechepso e Petosiris',quando:'c. 150\u2013120 a.C.',fonte:'Corpus de Nechepso e Petosiris, c. 150\u2013120 a.C.; primeira cole\xe7\xe3o dos fragmentos: Riess, 1892',detalhe:'A parte mais saborosa desta linha \xe9 o come\xe7o: a astrologia ocidental estreia com uma inven\xe7\xe3o de antiguidade. Os textos que fundam o mapa natal circulam assinados por um fara\xf3 e um sacerdote eg\xedpcios, e os dois s\xe3o pseud\xf4nimos de gregos que escreviam naquele momento em Alexandria. Dar pedigree antigo a coisa nova n\xe3o corrompeu a tradi\xe7\xe3o depois: est\xe1 l\xe1 desde o primeiro dia dela.'},'aspectos-maiores':{coisa:'Os cinco aspectos maiores',oQuePensam:'Geometria sagrada de origem perdida no tempo.',quemInventou:'a tradi\xe7\xe3o helen\xedstica; sistematizados por Ptolomeu',quando:'c. 150\u2013120 a.C.; sistematiza\xe7\xe3o no s\xe9c. II',fonte:'Ptolomeu, Tetrabiblos I.13, s\xe9c. II',detalhe:'Oposi\xe7\xe3o, tr\xedgono, quadratura e sextil n\xe3o s\xe3o desenho de mago: Ptolomeu tira os \xe2ngulos de propor\xe7\xf5es musicais aplicadas ao meio-c\xedrculo. E o crit\xe9rio dele para "combina" n\xe3o \xe9 elemento, \xe9 o g\xeanero do signo \u2014 a vers\xe3o "fogo com ar" \xe9 resumo de segunda m\xe3o. A conjun\xe7\xe3o, para ele, nem entra na lista.'},'casas-inteiras':{coisa:'As Casas Inteiras, uma casa por signo',oQuePensam:'Modinha de rede social, inven\xe7\xe3o de agora.',quemInventou:'\xe9 o m\xe9todo original da astrologia helen\xedstica',quando:'c. 150\u2013120 a.C.',fonte:'M\xe9todo helen\xedstico original; Holden, 1982 \xb7 Hand, 2000/2007 \xb7 Brennan, 2017',detalhe:'Volta e meia algu\xe9m chama Casas Inteiras de moda passageira, e \xe9 o contr\xe1rio: \xe9 com esse m\xe9todo que a astrologia de casas come\xe7ou, cada casa ocupando um signo inteiro, sem cortar grau no meio. Holden publicou sobre isso em 1982, Hand em 2000 e Brennan em 2017 \u2014 e na \xcdndia o sistema nunca deixou de ser usado. O que \xe9 moderno aqui \xe9 o nome em ingl\xeas.'},horaria:{coisa:'A astrologia hor\xe1ria, a pergunta que vira mapa',oQuePensam:'T\xe9cnica grega antiga, dos primeiros astr\xf3logos.',quemInventou:'astr\xf3logos do mundo isl\xe2mico',quando:'s\xe9c. IX',fonte:'Mundo isl\xe2mico, s\xe9c. IX; herdada por Lilly, 1647',detalhe:'Fazer a pergunta em voz alta e levantar o mapa do minuto da pergunta \xe9 uma das coisas mais engenhosas do of\xedcio \u2014 e n\xe3o \xe9 grega. O ramo amadurece no mundo isl\xe2mico, e \xe9 de l\xe1 que Lilly herda o que viraria o cora\xe7\xe3o da tradi\xe7\xe3o inglesa. Aquele clich\xea de que os \xe1rabes "s\xf3 preservaram" n\xe3o se sustenta: eles desenvolveram.'},'partes-arabes':{coisa:'As "partes \xe1rabes", como a Parte da Fortuna',oQuePensam:'Inven\xe7\xe3o \xe1rabe medieval, de cabo a rabo.',quemInventou:'o nome \xe9 do mundo isl\xe2mico; o conceito de lote \xe9 helen\xedstico',quando:'s\xe9c. IX o nome; c. 150\u2013120 a.C. o conceito',fonte:'Mundo isl\xe2mico, s\xe9c. IX; conceito de lote: tradi\xe7\xe3o helen\xedstica',detalhe:'O nome entrega uma origem, e a origem est\xe1 pela metade. Os lotes \u2014 pontos que se calculam por arco, sem astro nenhum ocupando aquele lugar do c\xe9u \u2014 j\xe1 est\xe3o na astrologia grega; o que os \xe1rabes fizeram foi multiplic\xe1-los. Ptolomeu, ali\xe1s, era dos que podavam: ele descarta quase todos.'},'aspectos-menores':{coisa:'Os aspectos menores: quintil, semiquadratura, sesquiquadratura',oQuePensam:'Refinamento antigo, para leitura avan\xe7ada.',quemInventou:'Johannes Kepler',quando:'1619',fonte:'Kepler, Harmonice Mundi, Livro IV, 1619',detalhe:'Quem inventou os \xe2ngulos "extras" do mapa foi o mesmo homem que descobriu como os planetas se movem. Kepler os tirou de raz\xf5es harm\xf4nicas, no mesmo livro em que trabalhava a m\xfasica das \xf3rbitas \u2014 e, para ele, astronomia e astrologia reformada n\xe3o brigavam. Ptolomeu reconhece cinco figuras e d\xe1 raz\xe3o para s\xf3 essas existirem.'},placidus:{coisa:'O sistema de casas Placidus',oQuePensam:'\xc9 o sistema tradicional, o de Ptolomeu.',quemInventou:'publicado por Placidus de Titis; o Swiss Ephemeris credita a inven\xe7\xe3o a Magini',quando:'1650',fonte:'Placidus de Titis, 1650; atribui\xe7\xe3o de inven\xe7\xe3o a Magini (1555\u20131617), via Swiss Ephemeris',detalhe:'\xc9 o padr\xe3o que quase todo site usa, e por isso parece o mais antigo de todos \u2014 \xe9 dos mais novos desta lista. Saiu impresso em 1650, e o Swiss Ephemeris, a biblioteca de c\xe1lculo que roda por baixo de quase todo software de astrologia, credita a inven\xe7\xe3o a Magini, um s\xe9culo antes. O Tetrabiblos, que costuma levar a fama, n\xe3o descreve sistema de casas nenhum.'},'urano-aquario':{coisa:'Urano como regente de Aqu\xe1rio',oQuePensam:'Reg\xeancia cl\xe1ssica, de toda a vida.',quemInventou:'Smith e Varley, depois da descoberta do planeta em 1781',quando:'1825\u20131828',fonte:'Ptolomeu, Tetrabiblos I.17, s\xe9c. II; atribui\xe7\xe3o a Urano: Smith, 1825 \xb7 Varley, 1828',detalhe:'Um planeta que ningu\xe9m tinha visto n\xe3o podia reger coisa nenhuma, e Urano s\xf3 apareceu num telesc\xf3pio em 1781. Quem \xe9 dono de Aqu\xe1rio na tradi\xe7\xe3o \xe9 Saturno \u2014 o signo \xe9 domic\xedlio dele, e domic\xedlio quer dizer o lugar em que o planeta est\xe1 em casa, mandando. A troca aparece por volta de 1825 e ainda estava em discuss\xe3o nos almanaques de 1834.'},'saturno-mestre':{coisa:'Saturno, o grande mestre e professor do mapa',oQuePensam:'Leitura antiga, o planeta das li\xe7\xf5es de sempre.',quemInventou:'Liz Greene',quando:'1976',fonte:'Liz Greene, 1976; contraponto antigo: V\xe9tio Valente, Antologias, s\xe9c. II',detalhe:'Todo post sobre retorno de Saturno traz um professor severo, e o professor tem menos idade que muito pai de fam\xedlia. Nos autores antigos ele \xe9 o mal\xe9fico maior, e o que muda a leitura \xe9 a seita \u2014 se a pessoa nasceu de dia ou de noite. A figura do mestre que amadurece foi publicada por Liz Greene em 1976.'},'mercurio-retrogrado':{coisa:'"Merc\xfario retr\xf3grado quebra aparelho e derruba contrato"',oQuePensam:'Regra antiga, avisada pelos astr\xf3logos h\xe1 s\xe9culos.',quemInventou:'sem autor identificado \u2014 a pesquisa procurou e n\xe3o achou',quando:'s\xe9culos XX e XXI, sem data exata',fonte:'Sem fonte antiga; o que Valente diz: Antologias, s\xe9c. II. Rastreio de imprensa: 1996',detalhe:'O bode expiat\xf3rio mais popular do calend\xe1rio n\xe3o tem certid\xe3o de nascimento. A pesquisa foi atr\xe1s do inventor da regra e voltou de m\xe3os vazias: isso circula como folclore de internet, e antes de 1996 nem os jornais falavam nisso. J\xe1 o que Valente escreve no s\xe9c. II \xe9 atraso e nada al\xe9m: para ele o retr\xf3grado "adia expectativas, a\xe7\xf5es e lucros".'},superlua:{coisa:'A Superlua',oQuePensam:'Fen\xf4meno astron\xf4mico cl\xe1ssico, com nome antigo e tudo.',quemInventou:'Richard Nolle, astr\xf3logo',quando:'1979',fonte:'Richard Nolle, revista Dell Horoscope, 1979',detalhe:'A manchete promete lua gigante e voc\xea sai de casa pra ver uma lua igualzinha \xe0 de ontem. Nem da astronomia o nome \xe9: quem cunhou "superlua" foi um astr\xf3logo, numa revista de hor\xf3scopo, e o termo t\xe9cnico \xe9 perigeu-siz\xedgia \u2014 lua cheia no ponto da \xf3rbita mais perto da Terra. Virou manchete de verdade s\xf3 a partir de 2011.'},'oito-fases':{coisa:'As oito fases da Lua e o significado de cada uma',oQuePensam:'Ciclo lunar milenar, uma li\xe7\xe3o por fase.',quemInventou:'Dane Rudhyar',quando:'1936',fonte:'Dane Rudhyar, The Astrology of Personality, 1936; The Lunation Cycle, 1967',detalhe:'O carrossel das oito fases circula como se fosse coisa de av\xf3, e \xe9 mais novo que a geladeira dela. Quem montou os oito tipos, com leitura de personalidade em cada um, foi Dane Rudhyar. Antes disso a divis\xe3o era outra: Ptolomeu trabalha com quatro quartos e fala de qualidades \u2014 quente, frio, seco, \xfamido \u2014, nunca de temperamento.'},'luas-cheias-nomes':{coisa:'Os nomes das luas cheias: Lua do Lobo, Lua do Morango',oQuePensam:'Nomes de povos origin\xe1rios, passados de gera\xe7\xe3o em gera\xe7\xe3o.',quemInventou:"Maine Farmers' Almanac, um almanaque agr\xedcola americano",quando:'anos 1930',fonte:"Maine Farmers' Almanac, anos 1930; lista impressa mais antiga verificada: Beard, 1918",detalhe:'Todo m\xeas o feed anuncia um nome novo pra lua cheia, e o nome nunca combina com o quintal daqui. A lista saiu de um almanaque de fazendeiro do nordeste dos Estados Unidos e descreve o calend\xe1rio agr\xedcola de l\xe1, o que explica a "Lua da Neve" cair no auge do ver\xe3o brasileiro. A impressa mais antiga que a pesquisa achou \xe9 de 1918, feita para os Boy Scouts, e nem \xe9 a famosa.'},'lua-de-sangue':{coisa:'A "Lua de Sangue"',oQuePensam:'Termo b\xedblico antigo para eclipse lunar.',quemInventou:'o pastor Mark Biltz; popularizado pelo livro de John Hagee',quando:'2008; o livro em 2013',fonte:'Mark Biltz, 2008 \xb7 John Hagee, Four Blood Moons, 2013',detalhe:'De tudo que soa b\xedblico nesta lista, este nome \xe9 mais novo que o primeiro iPhone. Quem passou a chamar eclipse lunar assim foi um pastor dos Estados Unidos, e a ideia virou livro popular cinco anos depois. A imagem est\xe1 em Joel 2:31, isso \xe9 verdade \u2014 o que n\xe3o est\xe1 l\xe1 \xe9 o nome do fen\xf4meno, e astr\xf4nomo n\xe3o usa.'},'taro-divinatorio':{coisa:'O tar\xf4 como sistema de adivinha\xe7\xe3o',oQuePensam:'Livro sagrado do Egito, guardado pelos sacerdotes.',quemInventou:'Antoine Court de G\xe9belin',quando:'1781',fonte:'Court de G\xe9belin, Le Monde primitif, vol. 8, "Du Jeu des Tarots", 1781',detalhe:'Antes de virar or\xe1culo, aquele baralho passou uns tr\xeas s\xe9culos e meio em mesa de jogo valendo dinheiro \u2014 e ainda hoje se joga tarocco na It\xe1lia. A virada tem cap\xedtulo e ano: um erudito franc\xeas publicou a tese eg\xedpcia em 1781, e o primeiro m\xe9todo de leitura saiu dois anos depois. D\xe1 seis s\xe9culos de imagem e dois e meio de leitura.'},'rider-waite':{coisa:'O baralho Rider-Waite-Smith como "o tar\xf4 tradicional"',oQuePensam:'\xc9 o desenho de sempre, o baralho original.',quemInventou:'Pamela Colman Smith desenhou; A. E. Waite dirigiu',quando:'1909\u20131911',fonte:'Rider-Waite-Smith, dezembro de 1909; A. E. Waite, The Pictorial Key to the Tarot, 1911',detalhe:'\xc9 o baralho que aparece em toda foto de tar\xf4, e \xe9 justamente por isso que ele parece o mais antigo. As 78 imagens s\xe3o de Pamela Colman Smith e sa\xedram em dezembro de 1909, com o livro no ano seguinte. Chamar esse baralho de tradicional apaga uns 470 anos de tar\xf4 que veio antes dele.'},'simbolos-borra-cafe':{coisa:'O dicion\xe1rio de s\xedmbolos da borra de caf\xe9',oQuePensam:'Tradi\xe7\xe3o turca milenar, s\xedmbolo por s\xedmbolo.',quemInventou:'"A Highland Seer" e Cicely Kent; quem repartiu a x\xedcara n\xe3o foi identificado',quando:'1881\u20131922',fonte:'Tea-Cup Reading and Fortune-Telling by Tea Leaves, "A Highland Seer", 1881 \xb7 Cicely Kent, 1922',detalhe:'P\xe1ssaro \xe9 not\xedcia, \xe2ncora \xe9 firmeza, anel \xe9 uni\xe3o: essa tabela toda tem endere\xe7o, e o endere\xe7o \xe9 a Gr\xe3-Bretanha. Ela foi impressa como brincadeira de sala de visita entre 1881 e 1922, no ambiente do ch\xe1 da tarde. J\xe1 a divis\xe3o da x\xedcara em al\xe7a, borda e fundo a pesquisa procurou e n\xe3o achou quem codificou: fica declarado.'},'signo-personalidade':{coisa:'"Seu signo \xe9 X, ent\xe3o voc\xea \xe9 assim"',oQuePensam:'Os antigos j\xe1 descreviam as doze personalidades.',quemInventou:'Alan Leo',quando:'c. 1895\u20131910',fonte:'Alan Leo, c. 1895\u20131910',detalhe:'Aquele quadro de "como cada signo age numa briga" tem menos idade que o cinema falado. O formato de retrato por signo \xe9 do ingl\xeas Alan Leo, na virada para o s\xe9c. XX, e foi ele que p\xf4s o Sol no centro de tudo. Para Ptolomeu, quem descreve o car\xe1ter s\xe3o Merc\xfario e a Lua \u2014 e n\xe3o existe cap\xedtulo das doze personalidades.'},'retratos-goodman':{coisa:'Os retratos de signo que circulam hoje',oQuePensam:'Descri\xe7\xe3o de sempre, herdada dos gregos.',quemInventou:'Linda Goodman',quando:'1968',fonte:'Linda Goodman, Sun Signs, 1968',detalhe:'O texto que voc\xea reconhece do seu signo \u2014 o jeito de amar, de brigar, de trabalhar \u2014 veio quase todo de um livro de banca. Linda Goodman publicou Sun Signs em 1968 e fixou o vocabul\xe1rio que o mercado repete at\xe9 agora. Valente, no s\xe9c. II, tamb\xe9m descreve signo por signo, e o retrato dele \xe9 irreconhec\xedvel pra quem l\xea hor\xf3scopo hoje.'},'potencial-psicologico':{coisa:'O mapa como retrato do potencial de cada um',oQuePensam:'A astrologia sempre foi ferramenta de autoconhecimento.',quemInventou:'Dane Rudhyar',quando:'1936',fonte:'Dane Rudhyar, The Astrology of Personality, 1936',detalhe:'A ideia de que o mapa mostra quem voc\xea pode vir a ser, e n\xe3o o que vai te acontecer, \xe9 a moldura que este app usa. Ela tem autor e ano: Dane Rudhyar reescreveu o vocabul\xe1rio inteiro da astrologia em 1936, trazendo Jung para dentro dela. A astrologia antiga era outra coisa \u2014 previa evento, num quadro fatalista.'},'nao-e-previsao':{coisa:'"N\xe3o \xe9 previs\xe3o, s\xe3o tend\xeancias"',oQuePensam:'A ressalva elegante e antiga da astrologia.',quemInventou:'Alan Leo, na defesa dos processos por adivinha\xe7\xe3o',quando:'1914 e 1917',fonte:'Processos de Alan Leo, Londres, 1914 e 1917',detalhe:'Essa frase est\xe1 na boca de todo app de astrologia, inclusive neste aqui. Ela nasceu num tribunal de Londres: Alan Leo respondia por adivinha\xe7\xe3o, e a defesa sustentava que aquilo era descri\xe7\xe3o de tend\xeancia, n\xe3o leitura de fortuna. A promotoria leu no julgamento uma linha em que o almanaque dele previa morte na fam\xedlia; ele foi condenado em 1917, e a ressalva virou heran\xe7a do mercado inteiro.'},'karma-mapa':{coisa:'Karma e vidas passadas no mapa',oQuePensam:'Camada antiga da astrologia, herdada do Oriente.',quemInventou:'a Sociedade Teos\xf3fica e seus herdeiros',quando:'a partir de 1875',fonte:'Teosofia, 1875 em diante',detalhe:'Quando algu\xe9m diz que voc\xea "veio pagar alguma coisa", o vocabul\xe1rio \xe9 bem mais novo que a astrologia. Karma, d\xedvida e vidas passadas n\xe3o est\xe3o em Ptolomeu, em Valente, em F\xedrmico, em Bonatti nem em Lilly. Entram no Ocidente pela Teosofia, uma sociedade fundada em 1875, que trouxe vocabul\xe1rio indiano para dentro do mapa.'},'nodos-missao':{coisa:'O Nodo Norte como "miss\xe3o da alma"',oQuePensam:'Sabedoria v\xe9dica antiga sobre o prop\xf3sito de vida.',quemInventou:'a camada teos\xf3fica; o formato popular \xe9 de Martin Schulman',quando:'a partir de 1875; Schulman, 1975',fonte:'Teosofia, 1875 em diante \xb7 Martin Schulman, Karmic Astrology, 1975',detalhe:'Se algu\xe9m j\xe1 leu a sua miss\xe3o de vida apontando um ponto do mapa, esse ponto tem etiqueta nova. O jyotish, que \xe9 a astrologia indiana, n\xe3o l\xea Rahu e Ketu como indicadores de carma pessoal \u2014 ent\xe3o o r\xf3tulo "v\xe9dico" n\xe3o para em p\xe9. A leitura chega pela Teosofia e vira livro em 1975, com Martin Schulman.'},'astrologia-tradicional':{coisa:'A "astrologia tradicional" que se ensina hoje',oQuePensam:'\xc9 a astrologia antiga direta da fonte, sem intermedi\xe1rio.',quemInventou:'Project Hindsight \u2014 Robert Schmidt, Ellen Black, Robert Zoller e Robert Hand',quando:'1992\u201393',fonte:'Project Hindsight, 1992\u201393',detalhe:'O que se vende hoje como "astrologia tradicional" \xe9 mais novo que muita gente que est\xe1 lendo isto. \xc9 uma reconstru\xe7\xe3o: a partir de 1992 um grupo de tradutores come\xe7ou a passar para o ingl\xeas textos gregos que ningu\xe9m tinha traduzido, e remontou o sistema a partir deles. Onde faltou texto entrou interpreta\xe7\xe3o, e h\xe1 disputa aberta entre os pr\xf3prios reconstrutores.'},'horoscopo-jornal':{coisa:'O hor\xf3scopo di\xe1rio por signo',oQuePensam:'\xc9 o formato cl\xe1ssico da astrologia, de sempre.',quemInventou:'R. H. Naylor, no jornal Sunday Express',quando:'24 de agosto de 1930',fonte:'R. H. Naylor, Sunday Express, 24/08/1930',detalhe:'D\xe1 pra marcar no calend\xe1rio o dia em que o hor\xf3scopo do seu feed nasceu: um domingo de agosto, num jornal de Londres, por causa de uma princesa rec\xe9m-nascida. Deu t\xe3o certo que virou se\xe7\xe3o fixa, e o formato de doze caixinhas veio da limita\xe7\xe3o de espa\xe7o da p\xe1gina. A parte antiga da astrologia \xe9 outra \u2014 o mapa inteiro, com hora e lugar.'},'porcentagem-compatibilidade':{coisa:'A porcentagem de compatibilidade entre signos',oQuePensam:'\xc9 c\xe1lculo tradicional, tirado de livro antigo.',quemInventou:'sem autor identificado \u2014 a pesquisa procurou e n\xe3o achou',quando:'s\xe9culo XX, sem data exata',fonte:'Sem fonte antiga; a escala que existe: Ptolomeu, Tetrabiblos IV.7, s\xe9c. II',detalhe:'Esta \xe9 uma das linhas que a pesquisa n\xe3o conseguiu datar, e a aus\xeancia j\xe1 \xe9 a resposta. N\xfamero de compatibilidade n\xe3o existe em fonte ocidental antiga, medieval ou renascentista: varreram Ptolomeu, Doroteu, M\u0101sh\u0101\u02beall\u0101h e Lilly e n\xe3o acharam nenhum. A r\xe9gua que a fonte antiga oferece \xe9 outra \u2014 quatro degraus ordenados, com um ter\xe7o dos pares de signos ficando de fora, sem nem se ver.'},'frequencias-hz':{coisa:'A frequ\xeancia em Hz de cada signo',oQuePensam:'Correspond\xeancia antiga entre o som e o c\xe9u.',quemInventou:'sem autor identificado \u2014 vocabul\xe1rio de marketing de bem-estar',quando:'s\xe9culos XX e XXI, sem data exata',fonte:'Sem fonte antiga; pedra e planta por signo, essas t\xeam: Culpeper, 1653',detalhe:'N\xe3o d\xe1 pra datar quem juntou signo e n\xfamero de hertz, porque n\xe3o h\xe1 autor: a pesquisa procurou e n\xe3o achou. Os n\xfameros que circulam \u2014 528, 432, 639 \u2014 v\xeam das chamadas frequ\xeancias solfeggio, que s\xe3o do s\xe9c. XX e n\xe3o aparecem em fonte antiga nenhuma. Pedra e planta por signo, essas sim t\xeam tradi\xe7\xe3o dat\xe1vel, e ela \xe9 de Culpeper, 1653.'},'app-astrologia':{coisa:'O app de astrologia como categoria',oQuePensam:'Parece que sempre existiu; j\xe1 se nasce com um no bolso.',quemInventou:'Co-Star, em Nova York',quando:'2017',fonte:'Co-Star, Nova York, 2017; The Pattern e Sanctuary, 2017\u20132019',detalhe:'A coisa mais nova desta lista \xe9 justamente a que voc\xea est\xe1 segurando. O g\xeanero "app de astrologia" nasceu em 2017, com o Co-Star em Nova York, e ganhou corpo com The Pattern e Sanctuary logo depois. Nenhuma tradi\xe7\xe3o antiga tem regra para leitura entregue por sistema, sem pessoa no circuito: a \xe9tica disso \xe9 toda contempor\xe2nea, inclusive a deste app.'}}}},1636,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"default",{enumerable:!0,get:function(){return o}});var o={tela:{titulo:'La edad real de cada cosa',subtitulo:'Parece milenario \xd7 tiene acta de nacimiento',intro:'Treinta cosas que el mercado vende como antiguas, con el a\xf1o en que apareci\xf3 cada una. La lista abre por la m\xe1s nueva.',ordenarPor:'ORDENAR',ordemMaisNovo:'La m\xe1s nueva primero',ordemMaisAntigo:'La m\xe1s antigua primero',ordemTema:'Por tema',rotuloQuem:'QUI\xc9N LO INVENT\xd3',rotuloQuando:'CU\xc1NDO',recibo:'RECIBO',abrir:'Ver la historia',fechar:'Cerrar',compartilhar:'Compartir',copiado:'Texto copiado \u2014 p\xe9galo donde quieras.',naoCopiou:'No se pudo copiar aqu\xed \u2014 selecciona el texto y c\xf3pialo.',idadeAnos:'{n} a\xf1os',idadeAnosAprox:'cerca de {n} a\xf1os',semData:'sin fecha',semDataLonga:'La investigaci\xf3n busc\xf3 al inventor y no lo encontr\xf3. Queda declarado.',comoContamos:'La edad aqu\xed es cuenta, no tabla: {ano} menos el a\xf1o que da la fuente. Por eso cambia sola cuando cambia el a\xf1o.',progresso:'Ya abriste {n} de {total}.',marca:'cosmicguide.cloud'},formato:{separadorMilhar:'.'},temas:{zodiaco:'El zod\xedaco',mapa:'La carta',planetas:'Los planetas',lua:'La Luna',oraculos:'Los or\xe1culos',leitura:'La forma de leer',mercado:'El mercado'},graus:{FP:{nome:'fuente primaria',glosa:'el texto antiguo lo dice, y la investigaci\xf3n se\xf1ala obra y cap\xedtulo'},TP:{nome:'tradici\xf3n posterior',glosa:'surgi\xf3 despu\xe9s del mundo antiguo, con autor y fecha conocidos'},IR:{nome:'invenci\xf3n reciente',glosa:'no tiene ra\xedz antigua: naci\xf3 en los siglos XIX, XX o XXI'},AM:{nome:'academia moderna',glosa:'es conclusi\xf3n de investigaci\xf3n hist\xf3rica, de los siglos XIX al XXI'}},compartilhar:{idade:'Edad real:',pensam:'Lo que se cree:',quem:'Qui\xe9n lo invent\xf3:',recibo:'Recibo:'},itens:{'zodiaco-12':{coisa:'El zod\xedaco de doce signos de 30\xb0',oQuePensam:'Tiene 5.000 a\xf1os y es lo m\xe1s antiguo de la astrolog\xeda.',quemInventou:'los astr\xf3nomos de Babilonia',quando:'c. 450\u2013400 a.C.',fonte:'Babilonia, c. 450\u2013400 a.C.',detalhe:'Esta es la l\xednea en que la respuesta honesta impresiona m\xe1s que la cifra redonda. Los babilonios cambiaron las constelaciones, que tienen tama\xf1os muy distintos, por doce rebanadas iguales de 30\xb0 en la ecl\xedptica \u2014 la franja del cielo por donde el Sol parece caminar. Sin esa grilla no existe decir "Marte en G\xe9minis" como coordenada, y sobre ella corre la astrolog\xeda entera hasta hoy.'},'homem-zodiacal':{coisa:'El Hombre Zodiacal, que le da a cada signo una parte del cuerpo',oQuePensam:'Est\xe1 en el Tetrabiblos, es lista de Ptolomeo.',quemInventou:'Manilio, en el poema Astronomica',quando:'siglo I d.C.',fonte:'Manilio, Astronomica II.453\u2013465, siglo I; corroborado por Vetio Valente',detalhe:'La lista que reparte el cuerpo entre los doce signos no est\xe1 donde todo el mundo jura que est\xe1. Ptolomeo enumera la correspondencia de los planetas; quien escribe la de los signos es Manilio, en un poema en verso. Y ah\xed Leo no se queda con el coraz\xf3n \u2014 se queda con los flancos y los om\xf3platos.'},'mapa-natal':{coisa:'La carta natal con Ascendente y casas',oQuePensam:'Los babilonios ya le\xedan cartas natales hace 5.000 a\xf1os.',quemInventou:'autores griegos de Alejandr\xeda, bajo los seud\xf3nimos Nechepso y Petosiris',quando:'c. 150\u2013120 a.C.',fonte:'Corpus de Nechepso y Petosiris, c. 150\u2013120 a.C.; primera colecci\xf3n de los fragmentos: Riess, 1892',detalhe:'Lo m\xe1s sabroso de esta l\xednea es el comienzo: la astrolog\xeda occidental debuta con una antig\xfcedad inventada. Los textos que fundan la carta natal circulan firmados por un fara\xf3n y un sacerdote egipcios, y los dos son seud\xf3nimos de griegos que escrib\xedan en ese momento en Alejandr\xeda. Darle pedigr\xed antiguo a algo nuevo no corrompi\xf3 la tradici\xf3n despu\xe9s: est\xe1 ah\xed desde su primer d\xeda.'},'aspectos-maiores':{coisa:'Los cinco aspectos mayores',oQuePensam:'Geometr\xeda sagrada de origen perdido en el tiempo.',quemInventou:'la tradici\xf3n helen\xedstica; sistematizados por Ptolomeo',quando:'c. 150\u2013120 a.C.; sistematizaci\xf3n en el siglo II',fonte:'Ptolomeo, Tetrabiblos I.13, siglo II',detalhe:'Oposici\xf3n, tr\xedgono, cuadratura y sextil no son dibujo de mago: Ptolomeo saca los \xe1ngulos de proporciones musicales aplicadas al medio c\xedrculo. Y su criterio para "combina" no es el elemento, es el g\xe9nero del signo \u2014 la versi\xf3n "fuego con aire" es resumen de segunda mano. La conjunci\xf3n, para \xe9l, ni entra en la lista.'},'casas-inteiras':{coisa:'Las Casas Enteras, una casa por signo',oQuePensam:'Moda de redes sociales, invenci\xf3n de ahora.',quemInventou:'es el m\xe9todo original de la astrolog\xeda helen\xedstica',quando:'c. 150\u2013120 a.C.',fonte:'M\xe9todo helen\xedstico original; Holden, 1982 \xb7 Hand, 2000/2007 \xb7 Brennan, 2017',detalhe:'Cada tanto alguien llama a las Casas Enteras moda pasajera, y es al rev\xe9s: con ese m\xe9todo empez\xf3 la astrolog\xeda de casas, cada casa ocupando un signo entero, sin cortar grados por la mitad. Holden public\xf3 sobre eso en 1982, Hand en 2000 y Brennan en 2017 \u2014 y en la India el sistema nunca dej\xf3 de usarse. Lo moderno aqu\xed es el nombre en ingl\xe9s.'},horaria:{coisa:'La astrolog\xeda horaria, la pregunta que se vuelve carta',oQuePensam:'T\xe9cnica griega antigua, de los primeros astr\xf3logos.',quemInventou:'astr\xf3logos del mundo isl\xe1mico',quando:'siglo IX',fonte:'Mundo isl\xe1mico, siglo IX; heredada por Lilly, 1647',detalhe:'Hacer la pregunta en voz alta y levantar la carta del minuto de la pregunta es de lo m\xe1s ingenioso del oficio \u2014 y no es griego. La rama madura en el mundo isl\xe1mico, y de ah\xed hereda Lilly lo que ser\xeda el coraz\xf3n de la tradici\xf3n inglesa. Aquel clich\xe9 de que los \xe1rabes "solo preservaron" no se sostiene: ellos desarrollaron.'},'partes-arabes':{coisa:'Las "partes \xe1rabes", como la Parte de la Fortuna',oQuePensam:'Invenci\xf3n \xe1rabe medieval, de punta a punta.',quemInventou:'el nombre es del mundo isl\xe1mico; el concepto de lote es helen\xedstico',quando:'siglo IX el nombre; c. 150\u2013120 a.C. el concepto',fonte:'Mundo isl\xe1mico, siglo IX; concepto de lote: tradici\xf3n helen\xedstica',detalhe:'El nombre entrega un origen, y el origen est\xe1 por la mitad. Los lotes \u2014 puntos que se calculan por arco, sin ning\xfan astro ocupando ese lugar del cielo \u2014 ya est\xe1n en la astrolog\xeda griega; lo que hicieron los \xe1rabes fue multiplicarlos. Ptolomeo, por cierto, era de los que podaban: los descarta casi todos.'},'aspectos-menores':{coisa:'Los aspectos menores: quintil, semicuadratura, sesquicuadratura',oQuePensam:'Refinamiento antiguo, para lectura avanzada.',quemInventou:'Johannes Kepler',quando:'1619',fonte:'Kepler, Harmonice Mundi, Libro IV, 1619',detalhe:'Quien invent\xf3 los \xe1ngulos "extra" de la carta fue el mismo hombre que descubri\xf3 c\xf3mo se mueven los planetas. Kepler los sac\xf3 de razones arm\xf3nicas, en el mismo libro donde trabajaba la m\xfasica de las \xf3rbitas \u2014 y para \xe9l astronom\xeda y astrolog\xeda reformada no peleaban. Ptolomeo reconoce cinco figuras y da raz\xf3n de que solo esas existan.'},placidus:{coisa:'El sistema de casas Placidus',oQuePensam:'Es el sistema tradicional, el de Ptolomeo.',quemInventou:'publicado por Placidus de Titis; el Swiss Ephemeris acredita la invenci\xf3n a Magini',quando:'1650',fonte:'Placidus de Titis, 1650; atribuci\xf3n de invenci\xf3n a Magini (1555\u20131617), v\xeda Swiss Ephemeris',detalhe:'Es el est\xe1ndar que usa casi todo sitio, y por eso parece el m\xe1s antiguo de todos \u2014 es de los m\xe1s nuevos de esta lista. Sali\xf3 impreso en 1650, y el Swiss Ephemeris, la biblioteca de c\xe1lculo que corre por debajo de casi todo software de astrolog\xeda, acredita la invenci\xf3n a Magini, un siglo antes. El Tetrabiblos, que suele llevarse la fama, no describe ning\xfan sistema de casas.'},'urano-aquario':{coisa:'Urano como regente de Acuario',oQuePensam:'Regencia cl\xe1sica, de toda la vida.',quemInventou:'Smith y Varley, despu\xe9s del descubrimiento del planeta en 1781',quando:'1825\u20131828',fonte:'Ptolomeo, Tetrabiblos I.17, siglo II; atribuci\xf3n a Urano: Smith, 1825 \xb7 Varley, 1828',detalhe:'Un planeta que nadie hab\xeda visto no pod\xeda regir nada, y Urano reci\xe9n apareci\xf3 en un telescopio en 1781. Quien manda en Acuario, en la tradici\xf3n, es Saturno \u2014 el signo es su domicilio, y domicilio quiere decir el lugar donde el planeta est\xe1 en su propia casa. El cambio aparece hacia 1825 y todav\xeda se discut\xeda en los almanaques de 1834.'},'saturno-mestre':{coisa:'Saturno, el gran maestro y profesor de la carta',oQuePensam:'Lectura antigua, el planeta de las lecciones de siempre.',quemInventou:'Liz Greene',quando:'1976',fonte:'Liz Greene, 1976; contrapunto antiguo: Vetio Valente, Antolog\xedas, siglo II',detalhe:'Todo posteo sobre retorno de Saturno trae un profesor severo, y ese profesor tiene menos edad que muchos padres de familia. En los autores antiguos \xe9l es el mal\xe9fico mayor, y lo que cambia la lectura es la secta \u2014 si la persona naci\xf3 de d\xeda o de noche. La figura del maestro que hace madurar la public\xf3 Liz Greene en 1976.'},'mercurio-retrogrado':{coisa:'"Mercurio retr\xf3grado rompe aparatos y tumba contratos"',oQuePensam:'Regla antigua, avisada por los astr\xf3logos hace siglos.',quemInventou:'sin autor identificado \u2014 la investigaci\xf3n busc\xf3 y no encontr\xf3',quando:'siglos XX y XXI, sin fecha exacta',fonte:'Sin fuente antigua; lo que dice Valente: Antolog\xedas, siglo II. Rastreo de prensa: 1996',detalhe:'El chivo expiatorio m\xe1s popular del calendario no tiene acta de nacimiento. La investigaci\xf3n fue a buscar al inventor de la regla y volvi\xf3 con las manos vac\xedas: circula como folclore de internet, y antes de 1996 ni los diarios hablaban de eso. Y lo que Valente escribe en el siglo II es demora y nada m\xe1s: para \xe9l el retr\xf3grado "posterga expectativas, acciones y ganancias".'},superlua:{coisa:'La Superluna',oQuePensam:'Fen\xf3meno astron\xf3mico cl\xe1sico, con nombre antiguo y todo.',quemInventou:'Richard Nolle, astr\xf3logo',quando:'1979',fonte:'Richard Nolle, revista Dell Horoscope, 1979',detalhe:'El titular anuncia una luna gigante y uno sale a la calle a ver una luna igualita a la de ayer. Ni de la astronom\xeda es el nombre: quien acu\xf1\xf3 "superluna" fue un astr\xf3logo, en una revista de hor\xf3scopos, y el t\xe9rmino t\xe9cnico es perigeo-sicigia \u2014 luna llena en el punto de la \xf3rbita m\xe1s cercano a la Tierra. Reci\xe9n se volvi\xf3 titular en serio a partir de 2011.'},'oito-fases':{coisa:'Las ocho fases de la Luna y lo que significa cada una',oQuePensam:'Ciclo lunar milenario, una lecci\xf3n por fase.',quemInventou:'Dane Rudhyar',quando:'1936',fonte:'Dane Rudhyar, The Astrology of Personality, 1936; The Lunation Cycle, 1967',detalhe:'El carrusel de las ocho fases circula como si fuera cosa de la abuela, y es m\xe1s nuevo que su heladera. Quien arm\xf3 los ocho tipos, con lectura de personalidad en cada uno, fue Dane Rudhyar. Antes de eso la divisi\xf3n era otra: Ptolomeo trabaja con cuatro cuartos y habla de cualidades \u2014 caliente, fr\xedo, seco, h\xfamedo \u2014, nunca de temperamento.'},'luas-cheias-nomes':{coisa:'Los nombres de las lunas llenas: Luna del Lobo, Luna de la Fresa',oQuePensam:'Nombres de pueblos originarios, pasados de generaci\xf3n en generaci\xf3n.',quemInventou:"Maine Farmers' Almanac, un almanaque agr\xedcola estadounidense",quando:'d\xe9cada de 1930',fonte:"Maine Farmers' Almanac, d\xe9cada de 1930; lista impresa m\xe1s antigua verificada: Beard, 1918",detalhe:'Cada mes el feed anuncia un nombre nuevo para la luna llena, y el nombre nunca combina con el patio de ac\xe1. La lista sali\xf3 de un almanaque de granjeros del noreste de Estados Unidos y describe el calendario agr\xedcola de all\xe1, lo que explica que la "Luna de la Nieve" caiga en pleno verano del sur. La impresa m\xe1s antigua que hall\xf3 la investigaci\xf3n es de 1918, hecha para los Boy Scouts, y ni siquiera es la famosa.'},'lua-de-sangue':{coisa:'La "Luna de Sangre"',oQuePensam:'T\xe9rmino b\xedblico antiguo para el eclipse lunar.',quemInventou:'el pastor Mark Biltz; popularizado por el libro de John Hagee',quando:'2008; el libro en 2013',fonte:'Mark Biltz, 2008 \xb7 John Hagee, Four Blood Moons, 2013',detalhe:'De todo lo que suena b\xedblico en esta lista, este nombre es m\xe1s nuevo que el primer iPhone. Quien empez\xf3 a llamar as\xed al eclipse lunar fue un pastor de Estados Unidos, y la idea se volvi\xf3 libro popular cinco a\xf1os despu\xe9s. La imagen est\xe1 en Joel 2:31, eso es cierto \u2014 lo que no est\xe1 ah\xed es el nombre del fen\xf3meno, y ning\xfan astr\xf3nomo lo usa.'},'taro-divinatorio':{coisa:'El tarot como sistema de adivinaci\xf3n',oQuePensam:'Libro sagrado de Egipto, guardado por los sacerdotes.',quemInventou:'Antoine Court de G\xe9belin',quando:'1781',fonte:'Court de G\xe9belin, Le Monde primitif, vol. 8, "Du Jeu des Tarots", 1781',detalhe:'Ese mazo estuvo en mesas de juego con dinero de por medio mucho antes de volverse or\xe1culo, y todav\xeda hoy se juega tarocco en Italia. El giro tiene cap\xedtulo y a\xf1o: un erudito franc\xe9s public\xf3 la tesis egipcia en 1781, y el primer m\xe9todo de lectura sali\xf3 dos a\xf1os despu\xe9s. Da seis siglos de imagen y dos y medio de lectura.'},'rider-waite':{coisa:'El mazo Rider-Waite-Smith como "el tarot tradicional"',oQuePensam:'Es el dibujo de siempre, el mazo original.',quemInventou:'Pamela Colman Smith lo dibuj\xf3; A. E. Waite lo dirigi\xf3',quando:'1909\u20131911',fonte:'Rider-Waite-Smith, diciembre de 1909; A. E. Waite, The Pictorial Key to the Tarot, 1911',detalhe:'Es el mazo que aparece en toda foto de tarot, y justamente por eso parece el m\xe1s antiguo. Las 78 im\xe1genes son de Pamela Colman Smith y salieron en diciembre de 1909, con el libro al a\xf1o siguiente. Llamar tradicional a ese mazo borra unos 470 a\xf1os de tarot que vinieron antes que \xe9l.'},'simbolos-borra-cafe':{coisa:'El diccionario de s\xedmbolos de la borra de caf\xe9',oQuePensam:'Tradici\xf3n turca milenaria, s\xedmbolo por s\xedmbolo.',quemInventou:'"A Highland Seer" y Cicely Kent; quien reparti\xf3 la taza no fue identificado',quando:'1881\u20131922',fonte:'Tea-Cup Reading and Fortune-Telling by Tea Leaves, "A Highland Seer", 1881 \xb7 Cicely Kent, 1922',detalhe:'P\xe1jaro es noticia, ancla es firmeza, anillo es uni\xf3n: esa tabla entera tiene direcci\xf3n, y la direcci\xf3n es Gran Breta\xf1a. Se imprimi\xf3 como juego de sala de visitas entre 1881 y 1922, en el ambiente del t\xe9 de la tarde. La divisi\xf3n de la taza en asa, borde y fondo, en cambio, la investigaci\xf3n busc\xf3 y no encontr\xf3 qui\xe9n la codific\xf3: queda declarado.'},'signo-personalidade':{coisa:'"Tu signo es X, entonces eres as\xed"',oQuePensam:'Los antiguos ya describ\xedan las doce personalidades.',quemInventou:'Alan Leo',quando:'c. 1895\u20131910',fonte:'Alan Leo, c. 1895\u20131910',detalhe:'Ese cuadrito de "c\xf3mo act\xfaa cada signo en una pelea" tiene menos edad que el cine sonoro. El formato de retrato por signo es del ingl\xe9s Alan Leo, en la vuelta al siglo XX, y fue \xe9l quien puso al Sol en el centro de todo. Para Ptolomeo, quien describe el car\xe1cter son Mercurio y la Luna \u2014 y no existe un cap\xedtulo de las doce personalidades.'},'retratos-goodman':{coisa:'Los retratos de signo que circulan hoy',oQuePensam:'Descripci\xf3n de siempre, heredada de los griegos.',quemInventou:'Linda Goodman',quando:'1968',fonte:'Linda Goodman, Sun Signs, 1968',detalhe:'El texto que reconoces de tu signo \u2014 la forma de amar, de pelear, de trabajar \u2014 sali\xf3 casi todo de un libro de quiosco. Linda Goodman public\xf3 Sun Signs en 1968 y fij\xf3 el vocabulario que el mercado repite hasta ahora. Valente, en el siglo II, tambi\xe9n describe signo por signo, y su retrato es irreconocible para quien lee hor\xf3scopos hoy.'},'potencial-psicologico':{coisa:'La carta como retrato del potencial de cada quien',oQuePensam:'La astrolog\xeda siempre fue herramienta de autoconocimiento.',quemInventou:'Dane Rudhyar',quando:'1936',fonte:'Dane Rudhyar, The Astrology of Personality, 1936',detalhe:'La idea de que la carta muestra qui\xe9n puedes llegar a ser, y no lo que te va a pasar, es el marco que usa esta app. Tiene autor y a\xf1o: Dane Rudhyar reescribi\xf3 el vocabulario entero de la astrolog\xeda en 1936, trayendo a Jung adentro. La astrolog\xeda antigua era otra cosa \u2014 predec\xeda eventos, en un cuadro fatalista.'},'nao-e-previsao':{coisa:'"No es predicci\xf3n, son tendencias"',oQuePensam:'La salvedad elegante y antigua de la astrolog\xeda.',quemInventou:'Alan Leo, en la defensa de los procesos por adivinaci\xf3n',quando:'1914 y 1917',fonte:'Procesos de Alan Leo, Londres, 1914 y 1917',detalhe:'Esa frase est\xe1 en la boca de toda app de astrolog\xeda, incluida esta. Naci\xf3 en un tribunal de Londres: Alan Leo respond\xeda por adivinaci\xf3n, y la defensa sosten\xeda que aquello era descripci\xf3n de tendencia, no lectura de fortuna. La fiscal\xeda ley\xf3 en el juicio una l\xednea donde su almanaque predec\xeda una muerte en la familia; fue condenado en 1917, y la salvedad qued\xf3 como herencia del mercado entero.'},'karma-mapa':{coisa:'Karma y vidas pasadas en la carta',oQuePensam:'Capa antigua de la astrolog\xeda, heredada de Oriente.',quemInventou:'la Sociedad Teos\xf3fica y sus herederos',quando:'a partir de 1875',fonte:'Teosof\xeda, 1875 en adelante',detalhe:'Cuando alguien dice que "viniste a pagar algo", el vocabulario es bastante m\xe1s nuevo que la astrolog\xeda. Karma, deuda y vidas pasadas no est\xe1n en Ptolomeo, en Valente, en F\xedrmico, en Bonatti ni en Lilly. Entran en Occidente por la Teosof\xeda, una sociedad fundada en 1875, que trajo vocabulario indio adentro de la carta.'},'nodos-missao':{coisa:'El Nodo Norte como "misi\xf3n del alma"',oQuePensam:'Sabidur\xeda v\xe9dica antigua sobre el prop\xf3sito de vida.',quemInventou:'la capa teos\xf3fica; el formato popular es de Martin Schulman',quando:'a partir de 1875; Schulman, 1975',fonte:'Teosof\xeda, 1875 en adelante \xb7 Martin Schulman, Karmic Astrology, 1975',detalhe:'Si alguien ya te ley\xf3 la misi\xf3n de vida se\xf1alando un punto de la carta, ese punto tiene etiqueta nueva. El jyotish, que es la astrolog\xeda india, no lee a Rahu y Ketu como indicadores de karma personal \u2014 as\xed que el r\xf3tulo "v\xe9dico" no se sostiene. La lectura llega por la Teosof\xeda y se vuelve libro en 1975, con Martin Schulman.'},'astrologia-tradicional':{coisa:'La "astrolog\xeda tradicional" que se ense\xf1a hoy',oQuePensam:'Es la astrolog\xeda antigua directo de la fuente, sin intermediario.',quemInventou:'Project Hindsight \u2014 Robert Schmidt, Ellen Black, Robert Zoller y Robert Hand',quando:'1992\u201393',fonte:'Project Hindsight, 1992\u201393',detalhe:'Lo que hoy se vende como "astrolog\xeda tradicional" es m\xe1s nuevo que mucha gente que est\xe1 leyendo esto. Es una reconstrucci\xf3n: a partir de 1992 un grupo de traductores empez\xf3 a pasar al ingl\xe9s textos griegos que nadie hab\xeda traducido, y rearm\xf3 el sistema desde ah\xed. Donde falt\xf3 texto entr\xf3 interpretaci\xf3n, y hay disputa abierta entre los propios reconstructores.'},'horoscopo-jornal':{coisa:'El hor\xf3scopo diario por signo',oQuePensam:'Es el formato cl\xe1sico de la astrolog\xeda, de siempre.',quemInventou:'R. H. Naylor, en el diario Sunday Express',quando:'24 de agosto de 1930',fonte:'R. H. Naylor, Sunday Express, 24/08/1930',detalhe:'Se puede marcar en el calendario el d\xeda en que naci\xf3 el hor\xf3scopo de tu feed: un domingo de agosto, en un diario de Londres, por una princesa reci\xe9n nacida. Funcion\xf3 tan bien que se volvi\xf3 secci\xf3n fija, y el formato de doce cajitas vino de la falta de espacio en la p\xe1gina. La parte antigua de la astrolog\xeda es otra \u2014 la carta entera, con hora y lugar.'},'porcentagem-compatibilidade':{coisa:'El porcentaje de compatibilidad entre signos',oQuePensam:'Es c\xe1lculo tradicional, sacado de libro antiguo.',quemInventou:'sin autor identificado \u2014 la investigaci\xf3n busc\xf3 y no encontr\xf3',quando:'siglo XX, sin fecha exacta',fonte:'Sin fuente antigua; la escala que s\xed existe: Ptolomeo, Tetrabiblos IV.7, siglo II',detalhe:'Esta es una de las l\xedneas que la investigaci\xf3n no logr\xf3 fechar, y la ausencia ya es la respuesta. N\xfamero de compatibilidad no existe en fuente occidental antigua, medieval ni renacentista: barrieron a Ptolomeo, a Doroteo, a M\u0101sh\u0101\u02beall\u0101h y a Lilly y no hallaron ninguno. Lo que tiene la tradici\xf3n es una escala de cuatro escalones, y ah\xed un tercio de los pares queda afuera \u2014 son signos que ni se ven.'},'frequencias-hz':{coisa:'La frecuencia en Hz de cada signo',oQuePensam:'Correspondencia antigua entre el sonido y el cielo.',quemInventou:'sin autor identificado \u2014 vocabulario del marketing de wellness',quando:'siglos XX y XXI, sin fecha exacta',fonte:'Sin fuente antigua; piedra y planta por signo, esas s\xed tienen: Culpeper, 1653',detalhe:'No se puede fechar a quien junt\xf3 signo y n\xfamero de hertz, porque no hay autor: la investigaci\xf3n busc\xf3 y no encontr\xf3. Los n\xfameros que circulan \u2014 528, 432, 639 \u2014 vienen de las llamadas frecuencias solfeggio, que son del siglo XX y no aparecen en ninguna fuente antigua. Piedra y planta por signo, esas s\xed tienen tradici\xf3n fechable, y es de Culpeper, 1653.'},'app-astrologia':{coisa:'La app de astrolog\xeda como categor\xeda',oQuePensam:'Parece que siempre existi\xf3; uno ya nace con una en el bolsillo.',quemInventou:'Co-Star, en Nueva York',quando:'2017',fonte:'Co-Star, Nueva York, 2017; The Pattern y Sanctuary, 2017\u20132019',detalhe:'La cosa m\xe1s nueva de esta lista es justamente la que tienes en la mano. El g\xe9nero "app de astrolog\xeda" naci\xf3 en 2017, con Co-Star en Nueva York, y tom\xf3 cuerpo con The Pattern y Sanctuary poco despu\xe9s. Ninguna tradici\xf3n antigua tiene regla para una lectura entregada por sistema, sin persona en el circuito: la \xe9tica de eso es toda contempor\xe1nea, incluida la de esta app.'}}}},1637,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"default",{enumerable:!0,get:function(){return t}});var t={tela:{titulo:'The real age of everything',subtitulo:'Looks ancient \xd7 has a birth certificate',intro:'Thirty things the market sells as ancient, with the year each one turned up. The list opens with the newest.',ordenarPor:'SORT',ordemMaisNovo:'Newest first',ordemMaisAntigo:'Oldest first',ordemTema:'By topic',rotuloQuem:'WHO INVENTED IT',rotuloQuando:'WHEN',recibo:'RECEIPTS',abrir:'See the story',fechar:'Close',compartilhar:'Share',copiado:'Text copied \u2014 paste it wherever you like.',naoCopiou:"Couldn't copy here \u2014 select the text and copy it.",idadeAnos:'{n} years',idadeAnosAprox:'about {n} years',semData:'no date',semDataLonga:'The research went looking for the inventor and came up empty. That is stated, not buried.',comoContamos:'The age here is arithmetic, not a lookup table: {ano} minus the year the source gives. That is why it ticks over on its own every New Year.',progresso:"You've opened {n} of {total}.",marca:'cosmicguide.cloud'},formato:{separadorMilhar:','},temas:{zodiaco:'The zodiac',mapa:'The chart',planetas:'The planets',lua:'The Moon',oraculos:'The oracles',leitura:'How it gets read',mercado:'The market'},graus:{FP:{nome:'primary source',glosa:'the ancient text says so, and the research points to the work and the chapter'},TP:{nome:'later tradition',glosa:'it turned up after the ancient world, with a known author and date'},IR:{nome:'recent invention',glosa:'no ancient root: it was born in the 19th, 20th or 21st century'},AM:{nome:'modern scholarship',glosa:'it is the conclusion of historical research, 19th to 21st century'}},compartilhar:{idade:'Real age:',pensam:'What people think:',quem:'Who invented it:',recibo:'Receipts:'},itens:{'zodiaco-12':{coisa:'The zodiac of twelve 30\xb0 signs',oQuePensam:"It's 5,000 years old and the oldest thing in astrology.",quemInventou:'the astronomers of Babylon',quando:'c. 450\u2013400 BC',fonte:'Babylon, c. 450\u2013400 BC',detalhe:'This is the line where the honest answer beats the round number. The Babylonians swapped the constellations, which come in wildly different sizes, for twelve equal 30\xb0 slices of the ecliptic \u2014 the band of sky the Sun appears to walk along. Without that grid there is no saying "Mars in Gemini" as a coordinate, and the whole of astrology still runs on it.'},'homem-zodiacal':{coisa:'The Zodiac Man, handing each sign a part of the body',oQuePensam:"It's in the Tetrabiblos, it's Ptolemy's list.",quemInventou:'Manilius, in the poem Astronomica',quando:'1st century AD',fonte:'Manilius, Astronomica II.453\u2013465, 1st century; corroborated by Vettius Valens',detalhe:'The list that shares the body out among the twelve signs is not where everyone swears it is. Ptolemy sets out the correspondence for the planets; the one for the signs comes from Manilius, in a poem written in verse. And there Leo does not get the heart \u2014 it gets the flanks and the shoulder blades.'},'mapa-natal':{coisa:'The birth chart with Ascendant and houses',oQuePensam:'The Babylonians were already reading birth charts 5,000 years ago.',quemInventou:'Greek authors in Alexandria, under the pen names Nechepso and Petosiris',quando:'c. 150\u2013120 BC',fonte:'Nechepso and Petosiris corpus, c. 150\u2013120 BC; first collection of the fragments: Riess, 1892',detalhe:'The tastiest part of this line is the beginning: Western astrology debuts with a made-up antiquity. The texts that found the birth chart circulate signed by an Egyptian pharaoh and an Egyptian priest, and both names are pen names for Greeks writing in Alexandria at that very moment. Giving new work an ancient pedigree did not spoil the tradition later on: it is there from day one.'},'aspectos-maiores':{coisa:'The five major aspects',oQuePensam:'Sacred geometry whose origin is lost in time.',quemInventou:'the Hellenistic tradition; systematised by Ptolemy',quando:'c. 150\u2013120 BC; systematised in the 2nd century',fonte:'Ptolemy, Tetrabiblos I.13, 2nd century',detalhe:'Opposition, trine, square and sextile are no wizard doodle: Ptolemy derives the angles from musical proportions applied to the half circle. And his test for "gets along" is not the element, it is the gender of the sign \u2014 the "fire with air" version is a second-hand summary. The conjunction, for him, does not even make the list.'},'casas-inteiras':{coisa:'Whole Sign Houses, one house per sign',oQuePensam:'A social-media fad, invented the day before yesterday.',quemInventou:'it is the original method of Hellenistic astrology',quando:'c. 150\u2013120 BC',fonte:'Original Hellenistic method; Holden, 1982 \xb7 Hand, 2000/2007 \xb7 Brennan, 2017',detalhe:'Every so often someone calls Whole Sign Houses a passing fad, and it is the other way round: house astrology started with that method, each house taking one entire sign, no degree cut down the middle. Holden published on it in 1982, Hand in 2000 and Brennan in 2017 \u2014 and in India the system never stopped being used. What is modern here is the English name.'},horaria:{coisa:'Horary astrology, the question that becomes a chart',oQuePensam:'Ancient Greek technique, from the first astrologers.',quemInventou:'astrologers of the Islamic world',quando:'9th century',fonte:'Islamic world, 9th century; inherited by Lilly, 1647',detalhe:'Asking the question out loud and casting a chart for the minute of the asking is one of the cleverest things in the craft \u2014 and it is not Greek. The branch matures in the Islamic world, and that is where Lilly picks up what would become the core of the English tradition. The clich\xe9 that Arab astrologers "merely preserved" does not hold: they developed.'},'partes-arabes':{coisa:'The "Arabic parts", such as the Part of Fortune',oQuePensam:'A medieval Arab invention, end to end.',quemInventou:'the name is from the Islamic world; the idea of a lot is Hellenistic',quando:'9th century for the name; c. 150\u2013120 BC for the idea',fonte:'Islamic world, 9th century; the lot as a concept: Hellenistic tradition',detalhe:'The name gives away an origin, and the origin is only half right. Lots \u2014 points worked out by arc, with no planet actually sitting at that spot in the sky \u2014 are already in Greek astrology; what the Arab tradition did was multiply them. Ptolemy, by the way, was one of the pruners: he throws out almost all of them.'},'aspectos-menores':{coisa:'The minor aspects: quintile, semisquare, sesquisquare',oQuePensam:'An ancient refinement, for advanced reading.',quemInventou:'Johannes Kepler',quando:'1619',fonte:'Kepler, Harmonice Mundi, Book IV, 1619',detalhe:'The man who invented the chart\'s "extra" angles is the same one who worked out how the planets move. Kepler pulled them from harmonic ratios, in the very book where he was chasing the music of the orbits \u2014 and to him astronomy and a reformed astrology were not at war. Ptolemy recognises five figures and gives a reason why only those exist.'},placidus:{coisa:'The Placidus house system',oQuePensam:"It's the traditional system, Ptolemy's own.",quemInventou:'published by Placidus de Titis; the Swiss Ephemeris credits the invention to Magini',quando:'1650',fonte:'Placidus de Titis, 1650; invention credited to Magini (1555\u20131617), via Swiss Ephemeris',detalhe:'It is the default on almost every website, which is exactly why it looks like the oldest one going \u2014 it is among the newest on this list. It went to print in 1650, and the Swiss Ephemeris, the calculation library running underneath nearly every astrology app, credits the invention to Magini a century earlier. The Tetrabiblos, which usually takes the credit, describes no house system at all.'},'urano-aquario':{coisa:'Uranus as the ruler of Aquarius',oQuePensam:'A classical rulership, the way it has always been.',quemInventou:'Smith and Varley, after the planet was found in 1781',quando:'1825\u20131828',fonte:'Ptolemy, Tetrabiblos I.17, 2nd century; assignment to Uranus: Smith, 1825 \xb7 Varley, 1828',detalhe:'A planet nobody had ever seen could not rule anything, and Uranus only turned up in a telescope in 1781. The one who owns Aquarius in the tradition is Saturn \u2014 the sign is his domicile, and domicile means the place where a planet sits in its own house. The swap shows up around 1825 and was still being argued over in the almanacs of 1834.'},'saturno-mestre':{coisa:'Saturn, the great teacher of the chart',oQuePensam:'An ancient reading, the planet of lessons forever.',quemInventou:'Liz Greene',quando:'1976',fonte:'Liz Greene, 1976; the ancient counterpoint: Vettius Valens, Anthologies, 2nd century',detalhe:"Every post about the Saturn return brings a stern teacher along, and that teacher is younger than plenty of people's dads. In the ancient authors he is the greater malefic, and what changes the reading is sect \u2014 whether the person was born by day or by night. The maturing-teacher figure was published by Liz Greene in 1976."},'mercurio-retrogrado':{coisa:'"Mercury retrograde breaks devices and kills contracts"',oQuePensam:'An old rule, flagged by astrologers for centuries.',quemInventou:'no author identified \u2014 the research looked and found none',quando:'20th and 21st centuries, no exact date',fonte:'No ancient source; what Valens says: Anthologies, 2nd century. Press trail: 1996',detalhe:'The calendar\'s favourite scapegoat has no birth certificate. The research went hunting for whoever invented the rule and came back empty-handed: it circulates as internet folklore, and the phrase does not even reach the general press before 1996. What Valens writes in the 2nd century is delay \u2014 a retrograde "delays expectations, actions and profits".'},superlua:{coisa:'The Supermoon',oQuePensam:'A classic astronomical event, ancient name and all.',quemInventou:'Richard Nolle, an astrologer',quando:'1979',fonte:'Richard Nolle, Dell Horoscope magazine, 1979',detalhe:'The headline promises a giant moon and you step outside to a moon exactly like yesterday\'s. The word is not even astronomy: "supermoon" was coined by an astrologer in a horoscope magazine, and the technical term is perigee syzygy \u2014 a full moon at the point of its orbit closest to Earth. It only became a real headline from 2011 on.'},'oito-fases':{coisa:'The eight Moon phases, each with its meaning',oQuePensam:'An age-old lunar cycle, one lesson per phase.',quemInventou:'Dane Rudhyar',quando:'1936',fonte:'Dane Rudhyar, The Astrology of Personality, 1936; The Lunation Cycle, 1967',detalhe:'The eight-phase carousel goes around as if it came from your grandmother, and it is newer than her fridge. The person who built the eight types, each with a personality reading, was Dane Rudhyar. Before that the split was different: Ptolemy works with four quarters and talks about qualities \u2014 hot, cold, dry, moist \u2014, never about temperament.'},'luas-cheias-nomes':{coisa:'The full moon names: Wolf Moon, Strawberry Moon',oQuePensam:'Indigenous names, handed down generation after generation.',quemInventou:"the Maine Farmers' Almanac, an American farming almanac",quando:'the 1930s',fonte:"Maine Farmers' Almanac, the 1930s; oldest printed list verified: Beard, 1918",detalhe:'Every month the feed announces a new name for the full moon, and the name never matches the backyard down here. The list came out of a farmers\' almanac from the northeastern United States and describes the growing calendar up there, which is why the "Snow Moon" lands at the height of a southern summer. The oldest printed list the research found is from 1918, made for the Boy Scouts, and it is not even the famous one.'},'lua-de-sangue':{coisa:'The "Blood Moon"',oQuePensam:'An ancient biblical term for a lunar eclipse.',quemInventou:'pastor Mark Biltz; popularised by John Hagee\'s book',quando:'2008; the book in 2013',fonte:'Mark Biltz, 2008 \xb7 John Hagee, Four Blood Moons, 2013',detalhe:'Of everything on this list that sounds biblical, this name is younger than the first iPhone. The person who started calling a lunar eclipse that was a pastor in the United States, and the idea became a popular book five years later. The image is in Joel 2:31, that much is true \u2014 what is not there is the name of the event, and no astronomer uses it.'},'taro-divinatorio':{coisa:'Tarot as a system of divination',oQuePensam:'A sacred book of Egypt, kept by the priests.',quemInventou:'Antoine Court de G\xe9belin',quando:'1781',fonte:'Court de G\xe9belin, Le Monde primitif, vol. 8, "Du Jeu des Tarots", 1781',detalhe:'Before it became an oracle, that deck spent some three and a half centuries on a card table with money on it \u2014 and tarocco is still played in Italy. The turn has a chapter and a year: a French scholar published the Egyptian thesis in 1781, and the first reading method came out two years later. That makes six centuries of imagery and two and a half of reading.'},'rider-waite':{coisa:'The Rider-Waite-Smith deck as "the traditional tarot"',oQuePensam:'It is the artwork of always, the original deck.',quemInventou:'Pamela Colman Smith drew it; A. E. Waite directed',quando:'1909\u20131911',fonte:'Rider-Waite-Smith, December 1909; A. E. Waite, The Pictorial Key to the Tarot, 1911',detalhe:'It is the deck in every tarot photo, and that is precisely why it looks like the oldest. The 78 images are by Pamela Colman Smith and came out in December 1909, with the book the following year. Calling that deck traditional wipes out some 470 years of tarot that came before it.'},'simbolos-borra-cafe':{coisa:'The symbol dictionary for coffee grounds',oQuePensam:'An age-old Turkish tradition, symbol by symbol.',quemInventou:'"A Highland Seer" and Cicely Kent; whoever mapped the cup was never identified',quando:'1881\u20131922',fonte:'Tea-Cup Reading and Fortune-Telling by Tea Leaves, "A Highland Seer", 1881 \xb7 Cicely Kent, 1922',detalhe:'Bird means news, anchor means steadiness, ring means union: that whole table has an address, and the address is Britain. It went to print as a drawing-room pastime between 1881 and 1922, in the world of afternoon tea. As for splitting the cup into handle, rim and bottom, the research went looking for who codified it and found nobody: that gets said out loud.'},'signo-personalidade':{coisa:'"Your sign is X, so you are like this"',oQuePensam:'The ancients already described the twelve personalities.',quemInventou:'Alan Leo',quando:'c. 1895\u20131910',fonte:'Alan Leo, c. 1895\u20131910',detalhe:'That little chart of "how each sign behaves in an argument" is younger than talking pictures. The sign-portrait format belongs to the Englishman Alan Leo, right at the turn into the 20th century, and he is the one who put the Sun at the centre of everything. For Ptolemy, what describes character is Mercury and the Moon \u2014 and there is no chapter of twelve personalities.'},'retratos-goodman':{coisa:'The sign portraits going around today',oQuePensam:'The description of always, inherited from the Greeks.',quemInventou:'Linda Goodman',quando:'1968',fonte:'Linda Goodman, Sun Signs, 1968',detalhe:'The text you recognise as your sign \u2014 how you love, how you argue, how you work \u2014 came almost entirely out of a paperback. Linda Goodman published Sun Signs in 1968 and fixed the vocabulary the market still repeats. Valens, in the 2nd century, also describes the signs one by one, and his portrait is unrecognisable to anyone reading horoscopes today.'},'potencial-psicologico':{coisa:'The chart as a portrait of what someone could become',oQuePensam:'Astrology was always a tool for self-knowledge.',quemInventou:'Dane Rudhyar',quando:'1936',fonte:'Dane Rudhyar, The Astrology of Personality, 1936',detalhe:"The idea that the chart shows who you might become, rather than what is going to happen to you, is the frame this app uses. It has an author and a year: Dane Rudhyar rewrote astrology's entire vocabulary in 1936, bringing Jung inside it. Ancient astrology was a different animal \u2014 it forecast events, inside a fatalistic picture."},'nao-e-previsao':{coisa:'"It is not prediction, these are tendencies"',oQuePensam:"Astrology's elegant old caveat.",quemInventou:'Alan Leo, defending himself against fortune-telling charges',quando:'1914 and 1917',fonte:'Alan Leo trials, London, 1914 and 1917',detalhe:"That sentence is in the mouth of every astrology app, this one included. It was born in a London courtroom: Alan Leo was answering a fortune-telling charge, and the defence held that this was a description of tendency, not a reading of fortune. The prosecution read out at trial a line where his almanac foretold a death in his family; the conviction came in 1917, and the caveat became the whole market's inheritance."},'karma-mapa':{coisa:'Karma and past lives in the chart',oQuePensam:'An ancient layer of astrology, inherited from the East.',quemInventou:'the Theosophical Society and its heirs',quando:'from 1875 on',fonte:'Theosophy, 1875 onwards',detalhe:'When somebody tells you that you "came here to settle something", the vocabulary is a good deal newer than astrology. Karma, debt and past lives are not in Ptolemy, in Valens, in Firmicus, in Bonatti or in Lilly. They enter the West through Theosophy, a society founded in 1875, which carried Indian vocabulary into the chart.'},'nodos-missao':{coisa:'The North Node as "your soul mission"',oQuePensam:'Ancient Vedic wisdom about life purpose.',quemInventou:'the Theosophical layer; the popular format is Martin Schulman\'s',quando:'from 1875 on; Schulman, 1975',fonte:'Theosophy, 1875 onwards \xb7 Martin Schulman, Karmic Astrology, 1975',detalhe:'If anyone has ever read your life mission off a single point in the chart, that point wears a new label. Jyotish, which is Indian astrology, does not read Rahu and Ketu as markers of personal karma \u2014 so the "Vedic" tag does not stand up. The reading arrives through Theosophy and becomes a book in 1975, with Martin Schulman.'},'astrologia-tradicional':{coisa:'The "traditional astrology" taught today',oQuePensam:'It is ancient astrology straight from the source, no middleman.',quemInventou:'Project Hindsight \u2014 Robert Schmidt, Ellen Black, Robert Zoller and Robert Hand',quando:'1992\u201393',fonte:'Project Hindsight, 1992\u201393',detalhe:'What gets sold today as "traditional astrology" is newer than plenty of the people reading this. It is a reconstruction: from 1992 on, a group of translators began putting into English Greek texts nobody had translated, and rebuilt the system out of them. Where the text ran out, interpretation came in, and there is open disagreement among the rebuilders themselves.'},'horoscopo-jornal':{coisa:'The daily horoscope by sun sign',oQuePensam:"It is astrology's classic format, the way it always was.",quemInventou:'R. H. Naylor, in the Sunday Express',quando:'24 August 1930',fonte:'R. H. Naylor, Sunday Express, 24/08/1930',detalhe:'You can mark on a calendar the day the horoscope in your feed was born: a Sunday in August, in a London paper, because of a newborn princess. It worked so well it became a fixed column, and the twelve-box format came from how little room the page had. The old part of astrology is something else \u2014 the whole chart, with a time and a place.'},'porcentagem-compatibilidade':{coisa:'The compatibility percentage between signs',oQuePensam:'A traditional calculation, taken from some old book.',quemInventou:'no author identified \u2014 the research looked and found none',quando:'20th century, no exact date',fonte:'No ancient source; the scale that does exist: Ptolemy, Tetrabiblos IV.7, 2nd century',detalhe:'This is one of the lines the research could not date, and the absence is already the answer. A compatibility number exists in no ancient, medieval or Renaissance Western source: they swept Ptolemy, Dorotheus, M\u0101sh\u0101\u02beall\u0101h and Lilly and found not one. What the tradition does have is a four-step scale, and in it a third of the pairs falls outside \u2014 signs that do not even see each other.'},'frequencias-hz':{coisa:'The Hz frequency of each sign',oQuePensam:'An ancient correspondence between sound and sky.',quemInventou:'no author identified \u2014 wellness marketing vocabulary',quando:'20th and 21st centuries, no exact date',fonte:'No ancient source; stone and plant by sign, those do have one: Culpeper, 1653',detalhe:'There is no dating whoever married a sign to a number of hertz, because there is no author: the research looked and did not find one. The numbers going around \u2014 528, 432, 639 \u2014 come from the so-called solfeggio frequencies, which are 20th-century and turn up in no ancient source. Stone and plant by sign, those do have a datable tradition, and it is Culpeper, 1653.'},'app-astrologia':{coisa:'The astrology app as a category',oQuePensam:'It feels like it always existed; you are born with one in your pocket.',quemInventou:'Co-Star, in New York',quando:'2017',fonte:'Co-Star, New York, 2017; The Pattern and Sanctuary, 2017\u20132019',detalhe:'The newest thing on this list is the one you are holding. The "astrology app" genre was born in 2017, with Co-Star in New York, and filled out with The Pattern and Sanctuary right after. No ancient tradition has a rule for a reading delivered by a system with no person in the loop: the ethics of that are entirely contemporary, this app\'s included.'}}}},1638,[]);